<?php
function weekly_output_pdf(array $r): void {
    $lines=['BELM GENERAL TECH SERVICE LIMITED','WEEKLY MAINTENANCE ACCOMPLISHMENT REPORT',$r['from'].' to '.$r['to'].' | '.$r['scope'],'Prepared by: '.$r['preparedBy'].' | Generated: '.$r['generatedAt'],isset($r['snapshotId'])?'Archived snapshot: '.$r['snapshotId']:'Live review copy',''];
    $s=$r['summary'];$lines[]=$s['completed'].' completed jobs | '.$s['machines'].' machines | '.$s['verified'].' verified | '.$s['unconfirmed'].' unconfirmed';
    foreach([true,false] as $verified){$lines[]='';$lines[]=$verified?'VERIFIED ACCOMPLISHMENTS':'UNCONFIRMED - PENDING CONFIRMATION';$found=false;foreach($r['items'] as $item){if($item['verified']!==$verified)continue;$found=true;$lines[]='';$lines[]=$item['jobCardNo'].' | '.$item['machine'].' | Fleet '.$item['fleet'];foreach(['title'=>'Work','technician'=>'Technician','date'=>'Date','status'=>'Status','fault'=>'Fault','diagnosis'=>'Diagnosis','findings'=>'Findings','solution'=>'Proposed solution','workDone'=>'Repair / maintenance performed','reviewer'=>'Manager reviewer','testResult'=>'Final test','testNotes'=>'Test observations'] as $key=>$label)$lines[]=$label.': '.($item[$key]?:'Not recorded');$lines[]='Missing documentation: '.(implode(', ',$item['missing'])?:'None');$lines[]='Follow-ups: '.(implode('; ',$item['followups'])?:'None');$lines[]='Supporting records:';foreach($item['sources'] as $source)$lines[]='  '.$source['type'].': '.$source['reference'].' | '.($source['relationship']??$source['status']??'Original source').' | ID '.$source['id'];}if(!$found)$lines[]='No records in this category.';}
    $lines[]='';$lines[]='Verification: '.$r['verificationRule'];$lines[]='';$lines[]='Prepared by: __________________  Reviewed by: __________________';$lines[]='Date: __________________';
    $wrapped=[];foreach($lines as $line){$plain=function_exists('iconv')?iconv('UTF-8','Windows-1252//TRANSLIT//IGNORE',(string)$line):preg_replace('/[^\x20-\x7E\n]/','?',(string)$line);foreach(explode("\n",wordwrap($plain===false?'':$plain,87,"\n",true)) as $part)$wrapped[]=$part;}
    $pages=array_chunk($wrapped,48);$objects=[];$refs=[];$font=3+count($pages)*2;
    foreach($pages as $i=>$page){$pageId=3+$i*2;$streamId=$pageId+1;$refs[]="$pageId 0 R";$stream="BT\n/F1 11 Tf\n43 798 Td\n14.5 TL\n";foreach($page as $line)$stream.='('.table_pdf_escape($line).") Tj\nT*\n";$stream.="ET\nBT /F1 9 Tf 43 28 Td (BELM | Weekly Maintenance | Page ".($i+1).' of '.count($pages).") Tj ET";$objects[$pageId]="<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 $font 0 R >> >> /Contents $streamId 0 R >>";$objects[$streamId]='<< /Length '.strlen($stream).">>\nstream\n".$stream."\nendstream";}
    $objects[1]='<< /Type /Catalog /Pages 2 0 R >>';$objects[2]='<< /Type /Pages /Count '.count($pages).' /Kids ['.implode(' ',$refs).'] >>';$objects[$font]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>';ksort($objects);$pdf="%PDF-1.4\n";$offsets=[0];foreach($objects as $id=>$object){$offsets[$id]=strlen($pdf);$pdf.="$id 0 obj\n$object\nendobj\n";}$xref=strlen($pdf);$pdf.='xref' ."\n0 ".(count($objects)+1)."\n0000000000 65535 f \n";for($i=1;$i<=count($objects);$i++)$pdf.=sprintf("%010d 00000 n \n",$offsets[$i]);$pdf.='trailer << /Size '.(count($objects)+1).' /Root 1 0 R >>'."\nstartxref\n$xref\n%%EOF";
    header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="BELM-Weekly-'.$r['from'].'.pdf"');header('Cache-Control: no-store');echo $pdf;
}
